import json
import zipfile
import re
import os
import xml.etree.ElementTree as ET


def flatten_json(obj, parent_key="", sep="."):
    """Flatten nested dicts into dot-joined keys.

    Example: {"a": {"b": 1}} -> {"a.b": 1}
    """
    out = {}
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else str(k)
            if isinstance(v, dict):
                out.update(flatten_json(v, new_key, sep=sep))
            else:
                out[new_key] = v
    else:
        out[parent_key] = obj
    return out


def localname(tag: str) -> str:
    # ElementTree tags may be '{uri}name' or 'name'
    if isinstance(tag, str) and tag.startswith("{") and "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def process_xml_text(xml_text: str, substitutions: dict, *, source_name: str) -> tuple[bytes, list[str]]:
    """Replace {{placeholders}} in raw XML text; remove line-seg cache elements."""
    missing_keys: set[str] = set()

    # Replace placeholders using regex so we can handle whitespace and avoid O(n*m) loops.
    def repl(m: re.Match) -> str:
        key = m.group(1).strip()
        if key in substitutions:
            return str(substitutions[key])
        missing_keys.add(key)
        return m.group(0)

    replaced = re.sub(r"\{\{([^{}]+)\}\}", repl, xml_text)

    # Register hp namespace to preserve prefix on serialization.
    try:
        root = ET.fromstring(replaced.encode("utf-8"))
    except ET.ParseError as e:
        raise RuntimeError(f"Failed to parse XML after replacement for {source_name}: {e}")

    if isinstance(root.tag, str) and root.tag.startswith("{"):
        uri = root.tag.split("}", 1)[0][1:]
        # Preserve original 'hp' prefix used by HWPML.
        ET.register_namespace("hp", uri)

    # Build a parent map since ElementTree doesn't provide getparent().
    parent = {c: p for p in root.iter() for c in p}

    # Remove layout cache elements that can cause overlapping text after edits.
    to_remove = []
    for elem in root.iter():
        ln = localname(elem.tag)
        # Template uses hp:linesegarray (lowercase). Task text mentions lineSegArray.
        if ln.lower() == "linesegarray" or ln == "lineSegArray":
            to_remove.append(elem)

    for elem in to_remove:
        p = parent.get(elem)
        if p is not None:
            p.remove(elem)

    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return out_bytes, sorted(missing_keys)


