    # Resolve inputs: prefer /root paths (task writes outputs there), fall back to CWD.
    candidates = [
        ("/root/event_data.json", "event_data.json"),
        ("/root/event_announcement_template.hwpx", "event_announcement_template.hwpx"),
    ]

    data_path = "/root/event_data.json" if os.path.exists("/root/event_data.json") else "event_data.json"
    template_path = (
        "/root/event_announcement_template.hwpx"
        if os.path.exists("/root/event_announcement_template.hwpx")
        else "event_announcement_template.hwpx"
    )

    output_path = "/root/event_announcement_ready.hwpx"

    if not os.path.exists(data_path):
        raise FileNotFoundError(f"event_data.json not found at {data_path!r}")
    if not os.path.exists(template_path):
        raise FileNotFoundError(f"event_announcement_template.hwpx not found at {template_path!r}")

