        data = json.load(f)

    substitutions = {}
    substitutions.update({k: v for k, v in data.items() if not isinstance(v, dict)})
    substitutions.update(flatten_json(data))

    # Read template zip into memory.
    with zipfile.ZipFile(template_path, "r") as zin:
        infos = zin.infolist()
        file_contents: dict[str, bytes] = {}
        for info in infos:
            file_contents[info.filename] = zin.read(info.filename)

    # Process each XML file that contains '{{'.
