        output_path, "w"
    ) as zout:
        for info in zin.infolist():
            content = file_contents[info.filename]
            # Ensure we keep mimetype uncompressed when present.
            compress_type = info.compress_type
            if info.filename == "mimetype":
                compress_type = zipfile.ZIP_STORED

            zi = zipfile.ZipInfo(info.filename, date_time=info.date_time)
            zi.compress_type = compress_type
            zi.comment = info.comment
            zi.extra = info.extra
            zi.create_system = info.create_system
            zi.create_version = info.create_version
            zi.extract_version = info.extract_version
            zi.flag_bits = info.flag_bits
            zi.volume = info.volume
            zi.internal_attr = info.internal_attr
            zi.external_attr = info.external_attr

            zout.writestr(zi, content)

    if warnings:
        for name, missing in warnings:
            print(f"WARNING: Unreplaced placeholders in {name}: {missing}")

