    # Build a parent map since ElementTree doesn't provide getparent().
    parent = {c: p for p in root.iter() for c in p}

    # Remove layout cache elements that can cause overlapping text after edits.
    to_remove = []
    for elem in root.iter():
        ln = localname(elem.tag)
        # Template uses hp:linesegarray (lowercase). Task text mentions lineSegArray.
        if ln.lower() == "linesegarray" or ln == "lineSegArray":
            to_remove.append(elem)

    for elem in to_remove:
        p = parent.get(elem)
        if p is not None:
            p.remove(elem)

    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return out_bytes, sorted(missing_keys)


def main():
    # Resolve inputs: prefer /root paths (task writes outputs there), fall back to CWD.
    candidates = [
        ("/root/event_data.json", "event_data.json"),
        ("/root/event_announcement_template.hwpx", "event_announcement_template.hwpx"),
    ]

    data_path = "/root/event_data.json" if os.path.exists("/root/event_data.json") else "event_data.json"
    template_path = (
        "/root/event_announcement_template.hwpx"
        if os.path.exists("/root/event_announcement_template.hwpx")
        else "event_announcement_template.hwpx"
    )

    output_path = "/root/event_announcement_ready.hwpx"

    if not os.path.exists(data_path):
        raise FileNotFoundError(f"event_data.json not found at {data_path!r}")
    if not os.path.exists(template_path):
        raise FileNotFoundError(f"event_announcement_template.hwpx not found at {template_path!r}")

    with open(data_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    substitutions = {}
    substitutions.update({k: v for k, v in data.items() if not isinstance(v, dict)})
    substitutions.update(flatten_json(data))

    # Read template zip into memory.
    with zipfile.ZipFile(template_path, "r") as zin:
        infos = zin.infolist()
        file_contents: dict[str, bytes] = {}
        for info in infos:
            file_contents[info.filename] = zin.read(info.filename)

    # Process each XML file that contains '{{'.
    warnings = []
    for name, raw in list(file_contents.items()):
        if not name.lower().endswith(".xml"):
            continue
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            continue

        if "{{" not in text:
            continue

        new_bytes, missing = process_xml_text(text, substitutions, source_name=name)
        file_contents[name] = new_bytes
        if missing:
            warnings.append((name, missing))

    # Write output zip, preserving original entry order and compression.
    with zipfile.ZipFile(template_path, "r") as zin, zipfile.ZipFile(
        output_path, "w"
    ) as zout:
        for info in zin.infolist():
            content = file_contents[info.filename]
            # Ensure we keep mimetype uncompressed when present.
            compress_type = info.compress_type
            if info.filename == "mimetype":
                compress_type = zipfile.ZIP_STORED

            zi = zipfile.ZipInfo(info.filename, date_time=info.date_time)
            zi.compress_type = compress_type
            zi.comment = info.comment
            zi.extra = info.extra
            zi.create_system = info.create_system
            zi.create_version = info.create_version
            zi.extract_version = info.extract_version
            zi.flag_bits = info.flag_bits
            zi.volume = info.volume
            zi.internal_attr = info.internal_attr
            zi.external_attr = info.external_attr

            zout.writestr(zi, content)

    if warnings:
        for name, missing in warnings:
            print(f"WARNING: Unreplaced placeholders in {name}: {missing}")

    print(f"Output written to {output_path}")


if __name__ == "__main__":
    main()
